// Mock review packets - swap for Okta groups API (privileged roles + exception grants FIRST, that is where the risk lives)
return [
  { json: { system: 'AWS Console (admin)', owner: 'Head of Infrastructure', ownerEmail: 'owner-1@example.com', members: [
    { user: 'dana@example.com', role: 'admin', grantedVia: 'exception', expiry: '2026-08-15' },
    { user: 'sam@example.com', role: 'admin', grantedVia: 'exception', expiry: 'none' } ] } },
  { json: { system: 'Workday (HR reports)', owner: 'VP People', ownerEmail: 'owner-2@example.com', members: [
    { user: 'marco@example.com', role: 'report-viewer', grantedVia: 'exception', expiry: 'none' },
    { user: 'lena@example.com', role: 'report-viewer', grantedVia: 'birthright', expiry: 'n/a' } ] } }
];

// One packet per system owner. Data owners review; IT orchestrates. Expiry-less exceptions get called out.
return $input.all().map(({ json: p }) => {
  const rows = p.members.map(m => '  ' + m.user + ' | ' + m.role + ' | via ' + m.grantedVia + ' | expiry: ' + m.expiry + (m.grantedVia === 'exception' && m.expiry === 'none' ? '  <-- NO EXPIRY, decide or time-box it' : '')).join('\n');
  return { json: {
    system: p.system, ownerEmail: p.ownerEmail,
    subject: '[Access review] ' + p.system + ' - ' + p.members.length + ' grant(s), reply keep/revoke per line',
    body: 'Quarterly access review for ' + p.system + ' (you are the data owner):\n\n' + rows + '\n\nReply to this email with keep or revoke per line within 7 days. No reply = we schedule the revoke and call you first.\nWhy this exists: exceptions without expiry are how least privilege quietly dies.'
  } };
});

// Shape the audit event for the shared ledger sub-workflow
return $input.all().map(({ json: p }) => ({ json: {
  eventType: 'access-review-dispatched', actor: 'automation', target: p.system,
  source: 'access-review-orchestrator', details: 'Review packet sent to data owner ' + p.ownerEmail
} }));
